package com.bank.replication;

import java.util.*;
import java.util.logging.*;

public class ReplicationDemo {
    private static final Logger log = Logger.getLogger("RDSReplication");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DatabaseCluster cluster = new DatabaseCluster(
                "nbi-ledger", true /*multiAz*/,
                List.of(new ReadReplica("replica-1", 2 /*lag seconds*/)));
        QueryRouter router = new QueryRouter(cluster);

        // Write goes to the primary; synchronous standby also gets it.
        log.info(() -> "WRITE transfer: " + router.write("debit SAV2001 50000"));

        // Heavy report to the asynchronous replica (lag acceptable).
        log.info(() -> "REPORT (bulk read): " + router.bulkRead("sum of all transfers today"));

        // Consistency-critical read must use the primary.
        log.info(() -> "BALANCE right after write: " + router.consistentRead("balance SAV2001"));

        // The stale-read pitfall if you read from a lagging replica.
        log.warning(() -> "If balance read from replica: " + router.staleReadFromReplica("balance SAV2001"));

        // Automatic Multi-AZ failover.
        log.severe(() -> "Primary AZ failed!");
        log.info(() -> "Failover: " + router.failover() + " (automatic, same endpoint)");
    }
}

// ─── Would be in QueryRouter.java ───
class QueryRouter {
    private final DatabaseCluster cluster;
    QueryRouter(DatabaseCluster cluster) { this.cluster = cluster; }

    // Writes always go to the primary (and its synchronous standby).
    String write(String sql) {
        return "primary applied '" + sql + "' + synchronous standby in sync";
    }

    // Bulk reads go to an async replica to offload the primary.
    String bulkRead(String sql) {
        if (cluster.replicas().isEmpty()) return "primary served '" + sql + "' (no replica)";
        return cluster.replicas().get(0).id() + " served '" + sql + "' (lag "
                + cluster.replicas().get(0).lagSeconds() + "s, acceptable for reports)";
    }

    // Consistency-critical reads must use the primary.
    String consistentRead(String sql) {
        return "primary served '" + sql + "' (read-after-write correct)";
    }

    String staleReadFromReplica(String sql) {
        return "replica served '" + sql + "' but may be "
                + cluster.replicas().get(0).lagSeconds() + "s stale — WRONG for read-after-write";
    }

    // Multi-AZ failover is automatic; the endpoint is unchanged.
    String failover() {
        if (!cluster.multiAz()) return "NO standby — manual replica promotion needed";
        cluster.promoteStandby();
        return "synchronous standby promoted automatically, zero data loss";
    }
}

// ─── Would be in DatabaseCluster.java ───
class DatabaseCluster {
    private final String id;
    private final boolean multiAz;
    private final List<ReadReplica> replicas;
    private boolean failedOver = false;
    DatabaseCluster(String id, boolean multiAz, List<ReadReplica> replicas) {
        this.id = id; this.multiAz = multiAz; this.replicas = replicas;
    }
    String id() { return id; }
    boolean multiAz() { return multiAz; }
    List<ReadReplica> replicas() { return replicas; }
    void promoteStandby() { this.failedOver = true; }
    boolean failedOver() { return failedOver; }
}

// ─── Would be in ReadReplica.java ───
class ReadReplica {
    private final String id;
    private final int lagSeconds;
    ReadReplica(String id, int lagSeconds) { this.id = id; this.lagSeconds = lagSeconds; }
    String id() { return id; }
    int lagSeconds() { return lagSeconds; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
